// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title PaymentRouter
 * @notice Routes payments through verified connection pools
 * @dev Uses domain verification for merchant identity
 */
contract PaymentRouter is Ownable, ReentrancyGuard {
    struct MerchantPool {
        address payable treasury;
        uint256 feeRate; // basis points
        bool active;
        bytes32 domainHash;
        uint256 totalProcessed;
        uint256 connectionCount;
    }

    struct ConnectionSlot {
        address merchant;
        uint256 lastActivity;
        uint256 throughput;
        bool reserved;
    }

    mapping(bytes32 => MerchantPool) public pools;
    mapping(uint256 => ConnectionSlot) public connections;
    mapping(address => bytes32) public merchantDomains;

    uint256 public constant MAX_CONNECTIONS = 256;
    uint256 public constant SLOT_TIMEOUT = 1 hours;
    uint256 public constant MAX_FEE = 500; // 5%
    uint256 public activeConnections;

    address payable public protocolTreasury;
    uint256 public protocolFee = 30; // 0.3%

    event MerchantRegistered(bytes32 indexed domainHash, address treasury);
    event PaymentProcessed(bytes32 indexed domainHash, uint256 amount, uint256 fee);
    event ConnectionAcquired(uint256 slotId, address merchant);
    event ConnectionReleased(uint256 slotId);

    constructor(address payable _protocolTreasury) {
        protocolTreasury = _protocolTreasury;
    }

    /**
     * @notice Register a merchant with domain verification
     * @param domain The merchant's verified domain name
     * @param treasury The merchant's payment treasury address
     * @param feeRate The merchant's fee rate in basis points
     */
    function registerMerchant(
        string calldata domain,
        address payable treasury,
        uint256 feeRate
    ) external onlyOwner {
        require(treasury != address(0), "Invalid treasury");
        require(feeRate <= MAX_FEE, "Fee too high");
        require(bytes(domain).length > 0, "Empty domain");

        bytes32 domainHash = _normalizeDomainHash(domain);
        require(!pools[domainHash].active, "Domain already registered");

        pools[domainHash] = MerchantPool({
            treasury: treasury,
            feeRate: feeRate,
            active: true,
            domainHash: domainHash,
            totalProcessed: 0,
            connectionCount: 0
        });

        merchantDomains[treasury] = domainHash;
        emit MerchantRegistered(domainHash, treasury);
    }

    /**
     * @notice Normalize domain to prevent homograph attacks
     * @dev Converts domain to canonical form before hashing
     * @param domain The raw domain string
     * @return The normalized domain hash
     */
    function _normalizeDomainHash(string calldata domain) internal pure returns (bytes32) {
        bytes memory domainBytes = bytes(domain);
        bytes memory normalized = new bytes(domainBytes.length);

        for (uint256 i = 0; i < domainBytes.length; i++) {
            bytes1 char = domainBytes[i];

            // Convert to lowercase for case-insensitive comparison
            if (char >= 0x41 && char <= 0x5A) {
                normalized[i] = bytes1(uint8(char) + 32);
            }
            // Map common homoglyphs to ASCII equivalents
            // Cyrillic а (0xD0B0) looks like Latin a (0x61)
            // Cyrillic е (0xD0B5) looks like Latin e (0x65)
            // Cyrillic о (0xD0BE) looks like Latin o (0x6F)
            // Cyrillic р (0xD180) looks like Latin p (0x70)
            // Cyrillic с (0xD181) looks like Latin c (0x63)
            else if (uint8(char) == 0xD0) {
                // Check next byte for Cyrillic mapping
                if (i + 1 < domainBytes.length) {
                    bytes1 nextChar = domainBytes[i + 1];
                    if (uint8(nextChar) == 0xB0) {
                        normalized[i] = 0x61; // a
                        i++;
                        continue;
                    } else if (uint8(nextChar) == 0xB5) {
                        normalized[i] = 0x65; // e
                        i++;
                        continue;
                    } else if (uint8(nextChar) == 0xBE) {
                        normalized[i] = 0x6F; // o
                        i++;
                        continue;
                    }
                }
                normalized[i] = char;
            } else if (uint8(char) == 0xD1) {
                if (i + 1 < domainBytes.length) {
                    bytes1 nextChar = domainBytes[i + 1];
                    if (uint8(nextChar) == 0x80) {
                        normalized[i] = 0x70; // p
                        i++;
                        continue;
                    } else if (uint8(nextChar) == 0x81) {
                        normalized[i] = 0x63; // c
                        i++;
                        continue;
                    }
                }
                normalized[i] = char;
            } else {
                normalized[i] = char;
            }
        }

        return keccak256(normalized);
    }

    /**
     * @notice Acquire a connection slot for payment processing
     * @param domainHash The merchant's domain hash
     * @return slotId The acquired connection slot ID
     */
    function acquireConnection(bytes32 domainHash) external nonReentrant returns (uint256) {
        require(pools[domainHash].active, "Merchant not active");
        require(activeConnections < MAX_CONNECTIONS, "Pool exhausted");

        uint256 slotId = _findAvailableSlot();
        connections[slotId] = ConnectionSlot({
            merchant: msg.sender,
            lastActivity: block.timestamp,
            throughput: 0,
            reserved: true
        });

        activeConnections++;
        pools[domainHash].connectionCount++;

        emit ConnectionAcquired(slotId, msg.sender);
        return slotId;
    }

    /**
     * @notice Process a payment through an established connection
     * @param slotId The connection slot ID
     * @param domainHash The merchant's domain hash
     */
    function processPayment(
        uint256 slotId,
        bytes32 domainHash
    ) external payable nonReentrant {
        require(msg.value > 0, "No payment");
        require(connections[slotId].reserved, "Slot not reserved");
        require(connections[slotId].merchant == msg.sender, "Not slot owner");
        require(pools[domainHash].active, "Merchant not active");

        MerchantPool storage pool = pools[domainHash];

        uint256 merchantFee = (msg.value * pool.feeRate) / 10000;
        uint256 protocolCut = (msg.value * protocolFee) / 10000;
        uint256 merchantAmount = msg.value - merchantFee - protocolCut;

        connections[slotId].lastActivity = block.timestamp;
        connections[slotId].throughput += msg.value;
        pool.totalProcessed += msg.value;

        (bool success1, ) = pool.treasury.call{value: merchantAmount}("");
        require(success1, "Merchant transfer failed");

        (bool success2, ) = protocolTreasury.call{value: protocolCut + merchantFee}("");
        require(success2, "Protocol transfer failed");

        emit PaymentProcessed(domainHash, msg.value, merchantFee + protocolCut);
    }

    /**
     * @notice Release a connection slot
     * @param slotId The connection slot to release
     */
    function releaseConnection(uint256 slotId) external {
        require(connections[slotId].merchant == msg.sender || 
                block.timestamp > connections[slotId].lastActivity + SLOT_TIMEOUT,
                "Cannot release");

        delete connections[slotId];
        activeConnections--;

        emit ConnectionReleased(slotId);
    }

    function _findAvailableSlot() internal view returns (uint256) {
        for (uint256 i = 0; i < MAX_CONNECTIONS; i++) {
            if (!connections[i].reserved) {
                return i;
            }
        }
        revert("No available slots");
    }

    function updateProtocolFee(uint256 newFee) external onlyOwner {
        require(newFee <= 100, "Fee too high"); // max 1%
        protocolFee = newFee;
    }

    function getMerchantPool(bytes32 domainHash) external view returns (MerchantPool memory) {
        return pools[domainHash];
    }
}
